INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Cliente Satisfecho como el Mejor Referidor', 'El cliente satisfecho de INVU es el mejor referidor porque tiene experiencia directa con el sistema y puede dar testimonio de su valor. Su recomendación tiene un peso enorme porque viene de alguien que ya confía en INVU. El programa de referidos convierte a los clientes satisfechos en una extensión del equipo de ventas, amplificando el alcance comercial de INVU sin costo adicional.', 'Un cliente de INVU con 2 locales recomienda el sistema a un colega restaurador. Le dice: "Nos cambió la vida: incluimos facturación electrónica nativa sin pagar extra a Nubefact, centralizamos el inventario de los 2 locales, y vemos reportes en tiempo real desde el celular. Además, el soporte es 24/7 en Perú." El colega confía en la recomendación y agenda una reunión con INVU. El cliente satisfecho cobra S/1,000 por la referencia.', NULL, NULL, NULL, 1);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "No Necesito Cambiar"', 'El referidor debe manejar la objeción del potencial cliente que dice "no necesito cambiar mi sistema". La respuesta es validar su postura, pero luego preguntar: "¿Tienes control de inventario en tiempo real? ¿Tu facturación electrónica está integrada o pagas aparte? ¿Puedes centralizar tus sedes y ver reportes consolidados?" Si el cliente responde que no a estas preguntas, el referidor puede mostrar que INVU es una mejora, no solo un cambio.', 'Un referidor le dice a un restaurador: "Entiendo. Pero ¿tienes control de inventario en tiempo real? ¿Tu facturación electrónica está integrada o pagas aparte? ¿Puedes centralizar tus sedes y ver reportes consolidados? INVU hace todo eso en un solo sistema. Te recomiendo que al menos los conozcas, no pierdes nada." El restaurador, que paga Nubefact aparte y no centraliza su inventario, se queda pensando y acepta la reunión.', NULL, NULL, NULL, 2);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "Es Caro"', 'El referidor debe manejar la objeción del potencial cliente que dice "es caro". La respuesta es validar su preocupación, pero luego mostrar que cuando se suman los costos de facturación electrónica aparte, soporte, y sistemas separados, INVU termina siendo más barato. Además, el control de inventario y la reducción de mermas pagan la inversión.', 'Un referidor le dice a un restaurador: "Yo pensé lo mismo, pero cuando sumas lo que pagas por facturación electrónica aparte, por soporte, y por sistemas separados, termina siendo más barato. Además, el control que te da en inventario y la reducción de mermas pagan la inversión. Vale la pena conocerlos." El restaurador, que no había sumado todos los costos, acepta la reunión.', NULL, NULL, NULL, 3);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "Lo Voy a Pensar"', 'El referidor debe manejar la objeción del potencial cliente que dice "lo voy a pensar". La respuesta es validar que es normal, pero ofrecer una demo sin compromiso: "Te propongo que los conozcas en una demo sin compromiso. Después de eso, si lo piensas y decides que no es para ti, no pasa nada." Esto quita presión y permite que el cliente avance en el proceso sin sentirse forzado.', 'Un referidor le dice a un restaurador: "Es normal. Te propongo que los conozcas en una demo sin compromiso. Después de eso, si lo piensas y decides que no es para ti, no pasa nada. ¿Qué te parece?" El restaurador, que se sentía presionado a decidir, se relaja y acepta la demo.', NULL, NULL, NULL, 4);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "Ya Tengo un Amigo que me Recomendó Otro Sistema"', 'El referidor debe manejar la objeción del potencial cliente que dice que ya tiene otra recomendación. La respuesta es no descalificar la otra opción, sino ofrecer una comparación informada: "Perfecto, lo importante es que encuentres la solución que mejor se adapte a ti. Te recomiendo que también conozcas a INVU para comparar. Así tomas una decisión informada."', 'Un referidor le dice a un restaurador: "Perfecto, lo importante es que encuentres la solución que mejor se adapte a ti. Te recomiendo que también conozcas a INVU para comparar. Así tomas una decisión informada. ¿Te parece?" El restaurador, que no quería cerrarse a una sola opción, acepta conocer a INVU.', NULL, NULL, NULL, 5);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción del Referidor "No Sé Vender"', 'El referidor que dice "no sé vender" debe recordar que no necesita vender. Solo necesita abrir la puerta y presentar a INVU. INVU es el que cierra. El único trabajo del referidor es conectar y asegurar la reunión. Eso lo puede hacer cualquier persona con contactos en la industria, sin importar su experiencia en ventas.', 'Un contador duda en referir a sus clientes porque cree que necesita saber vender. Pero luego recuerda: "No necesito vender. Solo necesito abrir la puerta y presentar a INVU. INVU es el que cierra. Mi único trabajo es conectar y asegurar la reunión." Con esta mentalidad, contacta a su primer cliente restaurantero y agenda una reunión con INVU.', NULL, NULL, NULL, 6);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'Los Niveles de Dominio del Referidor', 'El referidor pasa por 4 niveles: Básico (identifica oportunidades pero no las registra, pierde comisiones), Medio (presenta y registra, protege su comisión), Alto (construye una red activa, genera flujo constante de comisiones), y Gravedad Cero (se convierte en partner estratégico, con ingresos recurrentes y reconocimiento de INVU). El objetivo es llegar a Gravedad Cero: ser un socio estratégico de INVU con una red amplia y confiable.', 'Básico: Conoce a un restaurador pero no lo refiere formalmente. Pierde la comisión.
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Registro en CRM – Lo que no se registra, no existe', 'El referidor debe registrar la oportunidad formalmente mediante correo a lizeth@invupos.com con copia a jorge@invupos.com. Sin registro, no hay protección de oportunidad y no hay comisión. El registro es el paso que convierte el esfuerzo del referidor en dinero. No hay atajos.', 'Un referidor asegura una reunión pero se olvida de registrar. El negocio cierra, pero otro referidor había registrado la oportunidad antes. El primero pierde S/1,000. El segundo cobra. El primer referidor aprende la lección: lo que no se registra, no existe.', NULL, NULL, NULL, 8);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Bono Especial para Cuentas Consolidadas', 'Para cuentas consolidadas (más de 5 sedes), el referidor no solo cobra S/1,500, sino que tiene posibilidad de bono especial según el tamaño del negocio. Esto reconoce el valor de traer oportunidades de gran escala y incentiva al referidor a enfocarse en cadenas grandes.', 'Un referidor refiere una cadena de 15 restaurantes a INVU. Cobra S/1,500 de comisión base y además recibe un bono especial de S/500 por el tamaño del negocio. Total: S/2,000 por una sola referencia. El referidor se enfoca en buscar más cadenas grandes.', NULL, NULL, NULL, 9);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Valor de la Red de Contactos', 'La red de contactos del referidor es su activo más valioso. Cada contacto en la industria gastronómica es una oportunidad potencial de referido. El referidor debe cultivar su red, mantenerse en contacto con los dueños de restaurantes, y estar atento a las oportunidades. Una red amplia y activa es la clave para generar ingresos recurrentes.', 'Un proveedor de insumos tiene una lista de 100 clientes restauranteros. Cada mes, contacta a 5 de ellos para saber cómo va su negocio y si están considerando cambiar de sistema POS. Cuando encuentra a uno que está frustrado con su sistema actual, lo refiere a INVU. Su red de contactos es su máquina de generar ingresos.', NULL, NULL, NULL, 10);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Programa de Referidos como Extensión del Equipo de Ventas', 'El programa de referidos convierte a los referidores en una extensión del equipo de ventas de INVU, ampliando su alcance en el mercado peruano sin costo fijo. Los referidores abren puertas que el equipo comercial no podría abrir por sí mismo, aprovechando la confianza y las relaciones personales en la industria. Esto acelera el crecimiento de INVU y genera beneficios para todos.', 'El equipo de ventas de INVU no puede contactar a todos los restaurantes de Lima. Pero 100 referidores, cada uno con 10 contactos en la industria, pueden abrir 1,000 puertas. El programa de referidos multiplica el alcance comercial de INVU, generando más oportunidades de venta y más ingresos para los referidores.', NULL, NULL, NULL, 11);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Resultado Esperado – Una Red de Referidores Activos', 'El resultado esperado del programa de referidos es una red de referidores activos que generan un flujo constante de negocios calificados para el equipo comercial de INVU. Los referidores transforman su red de contactos en una fuente de ingresos adicionales, recomiendan a INVU con confianza, registran sus oportunidades correctamente, y cobran sus comisiones sin esfuerzo adicional. El programa de referidos se convierte en un motor de crecimiento para INVU y en una fuente de ingresos para los referidores.', 'Un año después del lanzamiento del programa, INVU tiene 200 referidores activos. Cada referidor refiere un promedio de 2 negocios al año. Son 400 oportunidades calificadas que llegan al equipo comercial. El equipo cierra el 40% de esas oportunidades: 160 nuevos clientes. Los referidores cobran sus comisiones. INVU crece. Todos ganan.', NULL, NULL, NULL, 12);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Partner – Un Socio Estratégico, No un Referidor', 'El Programa Partners es una evolución del programa de referidos. Mientras el referidor cobra una comisión fija (S/500, S/1,000, S/1,500), el Partner cobra el 8% del valor total del primer año del cliente (setup + 12 mensualidades), pagado en tres tramos. El Partner tiene un incentivo para traer clientes más grandes, porque su comisión crece proporcionalmente al tamaño del negocio. El referido es para contactos ocasionales; el Partner es para profesionales que quieren monetizar su red de contactos de manera recurrente.', 'Un contador refiere a un cliente de 1 sede: comisión S/532 (8% de S/6,650). Si el mismo contador refiere una cadena de 10 sedes: comisión S/6,057 (8% de S/75,708). El contador entiende que su red de contactos de clientes grandes vale mucho más. Se convierte en Partner y enfoca sus esfuerzos en las cuentas grandes.', NULL, NULL, NULL, 13);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El 8% del Valor del Primer Año – Cuanto más Grande, más Ganas', 'La comisión del Partner está directamente ligada al tamaño del negocio que refiere. No es una comisión fija; es el 8% del setup + 12 mensualidades del cliente. Un cliente de 1 sede genera S/532; un cliente de 3 sedes genera S/1,992; un cliente de 10 sedes genera S/6,057; una cuenta estratégica puede generar más de S/10,000. El Partner tiene incentivo para buscar los clientes más grandes y valiosos.', 'Un Partner tiene dos contactos: un restaurante de 1 sede y una cadena de 15 sedes. El primero le daría S/532; el segundo, con comisión preferente del 10%, le daría más de S/13,000. El Partner enfoca su tiempo en la cadena grande porque su esfuerzo se multiplica. La comisión sigue al valor del cliente.', NULL, NULL, NULL, 14);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'Pago en Tres Tramos – Cobro Rápido, Sin Esperas', 'La comisión total se paga en tres tramos: 40% al primer pago del cliente (setup + 1era mensualidad), 30% a los 60 días, 30% a los 90 días. El Partner no tiene que esperar 6 o 12 meses para cobrar su comisión completa. El primer pago llega tan pronto como el cliente firma y paga su primera factura. Esto genera confianza, flujo de caja rápido, y motiva a seguir refiriendo negocios.', 'Un Partner refiere una cadena de 10 sedes. Valor año 1: S/75,708. Comisión 8%: S/6,057. El Partner cobra S/2,423 al primer pago del cliente (40%), S/1,817 a los 60 días (30%), y S/1,817 a los 90 días (30%). En 3 meses, el Partner ha cobrado toda su comisión, sin esperar 12 meses como en otros programas. Esto es un gran diferenciador.', NULL, NULL, NULL, 15);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'Protección de Oportunidad por 90 Días – Tu Esfuerzo, tu Comisión', 'El Partner que registra primero un negocio queda como propietario de esa oportunidad durante 90 días. Si el negocio avanza y cierra dentro de ese plazo, la comisión es para el Partner que lo registró. Esto elimina la competencia desleal y protege el esfuerzo del Partner. La protección es la garantía de que su trabajo no será aprovechado por otro.', 'Un Partner registra una oportunidad de 5 sedes. Otro Partner intenta registrar el mismo negocio dos semanas después. INVU verifica que el primero ya lo tiene registrado y protege la oportunidad del Partner original. El primer Partner tiene la tranquilidad de que su comisión de S/1,992 está asegurada si el negocio cierra dentro de los 90 días.', NULL, NULL, NULL, 16);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'Bono Extraordinario de S/2,000 – La Recompensa por el Volumen', 'Si el Partner cierra más de 20 sucursales en 3 meses (de uno o varios clientes), gana un bono adicional de S/2,000. Esto incentiva al Partner a no limitarse a uno o dos clientes pequeños, sino a buscar múltiples clientes o cuentas grandes. El bono es por volumen y se suma a las comisiones ya generadas. Es un incentivo extra para escalar.', 'Un Partner cierra en un trimestre: una cadena de 10 sedes, otra de 8 sedes, y una de 5 sedes. Total: 23 sucursales. Gana comisiones: S/6,057 + S/4,846 + S/1,992 = S/12,895. Además, gana el bono de S/2,000. Ingreso trimestral: S/14,895. El bono transforma un buen trimestre en un trimestre excepcional.', NULL, NULL, NULL, 17);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'Comisión Preferente del 10% para Cuentas Estratégicas', 'Para cuentas de alto volumen (cadenas de 15+ sucursales), INVU ofrece una comisión preferente de hasta el 10%, acordada por escrito antes del cierre. Las cuentas estratégicas requieren más esfuerzo en la prospección y el contacto inicial. El Partner merece una compensación adicional por traer oportunidades de esta escala. Esto reconoce el valor de traer cuentas grandes.', 'Un Partner identifica una cadena de 20 restaurantes. Acuerda con INVU una comisión preferente del 10% antes del cierre. Valor año 1: S/150,000. Comisión: S/15,000. En comparación con el 8% (S/12,000), el Partner gana S/3,000 adicionales. El incentivo para buscar cuentas grandes es claro.', NULL, NULL, NULL, 18);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'Partners vs. Referidos – Dos Programas, Dos Perfiles', 'El Programa de Referidos está diseñado para contactos ocasionales que quieren ganar una comisión fija por una referencia simple. El Programa Partners está diseñado para profesionales (contadores, proveedores, consultores, agencias) que tienen una red de contactos activa y quieren monetizar su influencia de manera recurrente. El referido es para abrir una puerta; el Partner es para construir una relación estratégica.', 'Un cliente satisfecho de INVU recomienda a un amigo restaurador. Gana S/1,000. Es un referido. Un contador con 20 clientes restauranteros refiere a 5 de ellos a INVU en un año. Gana S/9,960 en comisiones. Es un Partner. El referido es para contactos sueltos; el Partner es para profesionales con red.', NULL, NULL, NULL, 19);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'La Comisión del 8% – Un Ejemplo con 1 Sede', 'Para un negocio de 1 sede, el setup aproximado es S/2,450 y la licencia mensual S/350. Valor año 1: S/2,450 + 12 x S/350 = S/6,650. Comisión 8%: S/532. Pagos: 40% = S/213 (primer pago), 30% = S/160 (60 días), 30% = S/160 (90 días). El Partner cobra S/532 en 3 meses por una referencia que le tomó 1-3 horas de trabajo.', 'Un Partner refiere un restaurante de 1 sede. El cliente firma y paga su primera factura. El Partner recibe S/213 en su primer pago. A los 60 días, S/160. A los 90 días, S/160. Total: S/532. El Partner cobra rápido y sin condiciones. El esfuerzo fue mínimo; la recompensa es concreta.', NULL, NULL, NULL, 20);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'La Comisión del 8% – Un Ejemplo con 3 Sedes', 'Para un negocio de 3 sedes, el setup aproximado es S/5,250 y las licencias mensuales S/1,638. Valor año 1: S/5,250 + 12 x S/1,638 = S/24,898. Comisión 8%: S/1,992. Pagos: 40% = S/797, 30% = S/598, 30% = S/598. El Partner cobra S/1,992 en 3 meses por una referencia que le tomó 1-3 horas de trabajo. La tasa de retorno es de S/664 a S/1,992 por hora.', 'Un contador refiere a un cliente que tiene 3 restaurantes. El cliente necesita centralización y facturación electrónica nativa. INVU cierra la venta. El contador recibe S/797 en su primer pago, S/598 a los 60 días, y S/598 a los 90 días. Total: S/1,992. El contador, que invirtió 3 horas en hacer la presentación, tiene un retorno de S/664 por hora.', NULL, NULL, NULL, 21);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'La Comisión del 8% – Un Ejemplo con 10 Sedes', 'Para una cadena de 10 sedes, el setup aproximado es S/10,150 y las licencias mensuales S/5,463. Valor año 1: S/75,708. Comisión 8%: S/6,057. Pagos: 40% = S/2,423, 30% = S/1,817, 30% = S/1,817. El Partner cobra S/6,057 en 3 meses por una referencia que le tomó 1-3 horas de trabajo. La tasa de retorno es de S/2,019 a S/6,057 por hora.', 'Un proveedor de insumos refiere una cadena de 10 restaurantes. INVU cierra la venta. El proveedor recibe S/2,423 en su primer pago, S/1,817 a los 60 días, y S/1,817 a los 90 días. Total: S/6,057. El proveedor, que invirtió 3 horas en contactar al dueño de la cadena, tiene un retorno de S/2,019 por hora. Su red de contactos se convierte en una máquina de generar dinero.', NULL, NULL, NULL, 22);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'La Comisión del 8% – Un Ejemplo con Cuenta Estratégica', 'Para una cuenta estratégica de más de 15 sedes, el valor año 1 puede superar los S/132,000. Con comisión preferente del 10%, la comisión es de S/13,200+. Pagos: 40% = S/5,280, 30% = S/3,960, 30% = S/3,960. El Partner cobra más de S/13,000 en 3 meses por una referencia que le tomó 1-3 horas de trabajo. La tasa de retorno es excepcional.', 'Un consultor refiere una cadena de 20 restaurantes. Acuerda una comisión preferente del 10% con INVU. Valor año 1: S/150,000. Comisión: S/15,000. El consultor recibe S/6,000 en su primer pago, S/4,500 a los 60 días, y S/4,500 a los 90 días. Total: S/15,000. El consultor, que invirtió 3 horas en contactar al CEO de la cadena, tiene un retorno de S/5,000 por hora. Su red de contactos se convierte en una fuente de ingresos principal.', NULL, NULL, NULL, 23);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'La Comparación con Otros Programas de Partners', 'Otros programas de partners ofrecen comisiones del 5% al 15% sobre la venta inicial, pero con condiciones: el cliente debe permanecer mínimo 12 meses, la comisión se paga fraccionada en todo ese período, y hay techos artificiales. INVU ofrece una comisión del 8% sobre el valor total del primer año, sin descuentos que reduzcan la base de cálculo, pago en tres tramos rápidos, protección de oportunidad, y bonos por rendimiento. INVU es más transparente, rápido y rentable.', 'En el programa X, la comisión es del 10%, pero el cliente debe permanecer 12 meses. Si el cliente cancela a los 8 meses, el Partner pierde parte de su comisión. En INVU, el Partner cobra el 40% al primer pago, el 30% a los 60 días, y el 30% a los 90 días. Si el cliente cancela después de los 90 días, el Partner ya cobró todo. El riesgo es menor y la transparencia es mayor.', NULL, NULL, NULL, 24);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Valor del Esfuerzo vs. la Comisión para el Partner', 'El Partner invierte entre 1 y 3 horas para identificar, contactar, presentar y registrar un negocio. Por ese esfuerzo, puede ganar S/532 (1 sede), S/1,992 (3 sedes), S/6,057 (10 sedes), o más de S/10,000 (cuenta estratégica). La tasa de retorno es excepcional: de S/177 a S/10,560 por hora. Si el Partner mantiene una red de contactos activa y refiere negocios regularmente, puede generar ingresos significativos con bajo esfuerzo.', 'Un Partner refiere 3 cadenas de 10 sedes al año. Comisión total: 3 x S/6,057 = S/18,171. Esfuerzo total: 3 x 3 horas = 9 horas. Tasa de retorno: S/2,019 por hora. El Partner gana casi S/18,000 en un año con 9 horas de trabajo. Si refiere 2 cuentas estratégicas, el ingreso supera los S/21,000. El esfuerzo es mínimo; el retorno es alto.', NULL, NULL, NULL, 25);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Riesgo Cero para el Partner', 'El Partner no asume ningún riesgo financiero. No invierte dinero, no firma contratos, no garantiza el pago del cliente. Su único riesgo es que el negocio referido no cierre dentro de los 90 días, lo que significaría que su esfuerzo de 1-3 horas no rinde fruto. Dado que INVU tiene un alto índice de cierre en negocios calificados, este riesgo es muy bajo. El Partner solo gana; nunca pierde.', 'Un Partner identifica un negocio potencial y lo registra. El negocio no cierra dentro de los 90 días por razones ajenas al Partner. El Partner no pierde dinero; solo perdió 3 horas de su tiempo. Pero tiene otros contactos en su red y sigue refiriendo. Eventualmente, uno de sus referidos cierra y cobra su comisión. El riesgo es mínimo y el potencial de ganancia es alto.', NULL, NULL, NULL, 26);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Perfil del Partner Ideal – Profesionales con Red de Contactos', 'El Partner ideal es cualquier profesional con acceso a una red de contactos en el sector gastronómico y retail: contadores, proveedores de insumos, consultores, agencias de marketing, dueños de locales, profesionales del sector. No necesita ser vendedor tecnológico; necesita tener contactos y credibilidad. Su red de contactos es su activo más valioso. Cuanto más amplia y activa sea su red, mayor será su potencial de ingresos.', 'Un contador con 20 clientes restauranteros tiene acceso a una red valiosa. Cada cliente es una oportunidad potencial de referido. Si refiere a 5 de sus clientes a INVU en un año, puede ganar S/9,960 o más. Un proveedor de insumos con 100 clientes restauranteros tiene una red aún más grande. El Partner no necesita vender; solo necesita abrir la puerta. Su red hace el resto.', NULL, NULL, NULL, 27);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'Las 7 Preguntas del Partner – Calificar Antes de Referir', 'El Partner debe hacer 7 preguntas de diagnóstico antes de referir un negocio: sector gastronómico o retail, número de sedes, facturación mensual, sistema actual y dolor, tomador de decisión, planes de expansión, y módulos adicionales (fidelización, e-commerce, autoservicio). Estas preguntas aseguran que el negocio califica y que INVU tiene una oportunidad real de cerrar la venta. También le permiten al Partner calcular su comisión potencial.', 'Un Partner contacta a un conocido dueño de una cadena de 5 restaurantes. Antes de referirlo, hace las 7 preguntas: "¿Cuántas sedes tienes? ¿Qué sistema usas hoy? ¿Cómo manejas la facturación electrónica? ¿Tienes planes de abrir más locales?" Al obtener las respuestas, confirma que el negocio califica y que el valor potencial de la comisión es S/1,992. Ahora está motivado para referir el negocio.', NULL, NULL, NULL, 28);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Framework Gravity para el Partner', 'El Partner aplica el Framework Gravity de manera adaptada: Diagnóstico (identificar el negocio y hacer las 7 preguntas), Educación (presentar INVU como el socio estratégico recomendado), Comparación (mostrar que INVU integra todo en un solo sistema), Construcción de Valor (destacar los beneficios: control total, facturación nativa, e-commerce sin comisiones), y Cierre (asegurar la reunión). El Partner no cierra ventas; cierra reuniones.', 'Un Partner identifica un negocio potencial. Hace el diagnóstico: "Tienes 3 locales, pagas Nubefact aparte, no centralizas inventario." Educa: "Te recomiendo INVU, el sistema que usan más de 5,000 restaurantes en Latam." Compara: "Otros sistemas te cobran la facturación aparte; INVU lo incluye." Construye valor: "Con INVU, centralizas tus 3 locales en un solo panel." Cierra: "¿Qué te parece si los contacto para que te hagan una demo?" El Partner asegura la reunión y su comisión está en marcha.', NULL, NULL, NULL, 29);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Registro Correcto – Protege tu Comisión', 'El Partner debe registrar la oportunidad formalmente mediante correo a lizeth@invupos.com con copia a jorge@invupos.com, incluyendo: nombre del negocio, nombre y cargo del tomador de decisión, teléfono y correo de contacto, número de sedes, facturación aproximada, sistema actual, y necesidades identificadas. Sin este registro, la comisión del Partner no está protegida. Lo que no está registrado, no existe.', 'Un Partner asegura una reunión con un dueño de una cadena de 10 sedes, pero no envía el correo de registro. Otro Partner registra el mismo negocio. El primero pierde la comisión de S/6,057. El segundo cobra. El primer Partner aprende la lección: lo que no se registra, no existe. A partir de ese momento, registra todas sus oportunidades inmediatamente.', NULL, NULL, NULL, 30);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "No Necesito Cambiar" para el Partner', 'El Partner debe manejar la objeción del potencial cliente que dice "no necesito cambiar mi sistema". La respuesta es validar su postura, pero luego preguntar: "¿Tienes control de inventario en tiempo real? ¿Tu facturación electrónica está integrada o pagas aparte? ¿Puedes centralizar tus sedes y ver reportes consolidados? ¿Tienes e-commerce propio sin comisiones?" Si el cliente responde que no, el Partner puede mostrar que INVU es una mejora, no solo un cambio.', 'Un Partner le dice a un restaurador: "Entiendo. Pero ¿tienes control de inventario en tiempo real? ¿Tu facturación electrónica está integrada o pagas aparte? ¿Puedes centralizar tus sedes y ver reportes consolidados? ¿Tienes e-commerce propio sin comisiones? INVU hace todo eso en un solo sistema. Te recomiendo que al menos los conozcas, no pierdes nada." El restaurador, que paga Nubefact aparte y no centraliza su inventario, acepta la reunión.', NULL, NULL, NULL, 31);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "Es Caro" para el Partner', 'El Partner debe manejar la objeción del potencial cliente que dice "es caro". La respuesta es validar su preocupación, pero luego mostrar que cuando se suman los costos de facturación electrónica aparte, soporte, sistemas separados, y comisiones de delivery apps, INVU termina siendo más barato o igual. Además, el control de inventario y la reducción de mermas pagan la inversión.', 'Un Partner le dice a un restaurador: "Yo conozco el sistema y sé que cuando sumas lo que pagas por facturación electrónica aparte, por soporte, por sistemas separados, y por comisiones de delivery apps, termina siendo más barato o igual. Además, el control que te da en inventario y la reducción de mermas pagan la inversión. Vale la pena conocerlos." El restaurador, que no había sumado todos los costos, acepta la reunión.', NULL, NULL, NULL, 32);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "Lo Voy a Pensar" para el Partner', 'El Partner debe manejar la objeción del potencial cliente que dice "lo voy a pensar". La respuesta es validar que es normal, pero ofrecer una demo sin compromiso: "Te propongo que los conozcas en una demo sin compromiso. Después de eso, si lo piensas y decides que no es para ti, no pasa nada." Esto quita presión y permite que el cliente avance en el proceso sin sentirse forzado.', 'Un Partner le dice a un restaurador: "Es normal. Te propongo que los conozcas en una demo sin compromiso. Después de eso, si lo piensas y decides que no es para ti, no pasa nada. ¿Qué te parece?" El restaurador, que se sentía presionado a decidir, se relaja y acepta la demo.', NULL, NULL, NULL, 33);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción "Ya Tengo un Amigo que me Recomendó Otro Sistema" para el Partner', 'El Partner debe manejar la objeción del potencial cliente que dice que ya tiene otra recomendación. La respuesta es no descalificar la otra opción, sino ofrecer una comparación informada: "Perfecto, lo importante es que encuentres la solución que mejor se adapte a ti. Te recomiendo que también conozcas a INVU para comparar. Así tomas una decisión informada."', 'Un Partner le dice a un restaurador: "Perfecto, lo importante es que encuentres la solución que mejor se adapte a ti. Te recomiendo que también conozcas a INVU para comparar. Así tomas una decisión informada. ¿Te parece?" El restaurador, que no quería cerrarse a una sola opción, acepta conocer a INVU.', NULL, NULL, NULL, 34);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Manejo de la Objeción del Partner "No Sé Vender"', 'El Partner que dice "no sé vender" debe recordar que no necesita vender. Solo necesita abrir la puerta y presentar a INVU. INVU es el que cierra. El único trabajo del Partner es conectar y asegurar la reunión. Eso lo puede hacer cualquier profesional con contactos en la industria, sin importar su experiencia en ventas. Además, el 8% del valor del primer año del cliente es una comisión justa por abrir esa puerta. Vale la pena el esfuerzo.', 'Un contador duda en referir a sus clientes porque cree que necesita saber vender. Pero luego recuerda: "No necesito vender. Solo necesito abrir la puerta y presentar a INVU. INVU es el que cierra. Mi único trabajo es conectar y asegurar la reunión. Además, el 8% del valor del primer año del cliente es una comisión justa por abrir esa puerta." Con esta mentalidad, contacta a su primer cliente restaurantero y agenda una reunión con INVU.', NULL, NULL, NULL, 35);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'Los Niveles de Dominio del Partner', 'El Partner pasa por 4 niveles: Básico (identifica oportunidades pero no las registra, pierde comisiones), Medio (presenta y registra, protege su comisión), Alto (construye una red activa, refiere negocios regularmente, genera S/10,000+ anuales), y Gravedad Cero (se convierte en partner estratégico, con ingresos recurrentes, reconocimiento de INVU, y comisiones que superan los S/20,000 anuales). El objetivo es llegar a Gravedad Cero: ser un socio estratégico de INVU.', 'Básico: Conoce a un restaurador pero no lo refiere formalmente. Pierde la comisión.
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Potencial de Ingresos Ilimitado del Partner', 'El Partner puede referir múltiples negocios y acumular comisiones sin límite. No hay tope de ingresos ni restricción de cantidad de referidos. Cuantos más negocios conecte, más comisiones acumula. Si refiere negocios grandes (3-10 sedes), sus comisiones pueden superar los S/20,000 o S/50,000 anuales. El potencial de ingresos es ilimitado y está directamente ligado al tamaño y cantidad de los negocios que refiere.', 'Un Partner refiere 5 negocios de 3 sedes al año: 5 x S/1,992 = S/9,960.
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Programa Partners como Extensión del Equipo de Ventas', 'El programa de partners convierte a los partners en una extensión del equipo de ventas de INVU, ampliando su alcance en el mercado peruano sin costo fijo. Los partners abren puertas que el equipo comercial no podría abrir por sí mismo, aprovechando la confianza y las relaciones personales en la industria. Esto acelera el crecimiento de INVU y genera beneficios para todos. Los partners ganan comisiones significativas; INVU gana clientes calificados; el ecosistema crece.', 'El equipo de ventas de INVU no puede contactar a todos los restaurantes de Lima. Pero 100 partners, cada uno con 10 contactos en la industria, pueden abrir 1,000 puertas. El programa de partners multiplica el alcance comercial de INVU, generando más oportunidades de venta y más ingresos para los partners. INVU crece; los partners cobran comisiones; la red se expande. Todos ganan.', NULL, NULL, NULL, 38);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Hunter – Cazador, No Esperador', 'El Hunter no espera leads; sale a la calle a identificar negocios, contactar tomadores de decisión, presentar el valor de INVU y cerrar ventas. El Hunter es un cazador de oportunidades que construye su propio mercado. Su ingreso depende directamente de su esfuerzo: 15 visitas/semana, 10 reuniones con decisores, 5 demos/mes, 2-3 cierres/mes. El que no visita, no vende.', 'Un Hunter inicia su semana con una agenda de 15 visitas a restaurantes. No espera que el teléfono suene; sale a la calle, entra a los locales, identifica al dueño o gerente, y hace su pitch. En la primera semana, logra 5 reuniones. En la segunda, 3 demos. En la tercera, 2 cierres. Su ingreso: S/4,298. El Hunter que espera, no cobra. El que caza, triunfa.', NULL, NULL, NULL, 39);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Ritmo del Hunter Ganador – La Disciplina que Multiplica Ingresos', 'El Hunter ganador mantiene un ritmo de: 15 visitas/semana, 30 interacciones/mes, 10 reuniones con decisores/mes, 5 demos/mes, 2-3 cierres/mes. El ingreso del Hunter está directamente ligado a su esfuerzo. No hay atajos. La prospección constante y el registro meticuloso en CRM son la base del éxito. El ritmo es la disciplina que separa al Hunter promedio del Hunter Elite.', 'Un Hunter tiene un mes de 4 semanas. Se fija metas diarias: 3 visitas a restaurantes, 1 interacción por teléfono, 1 reunión con decisor. Al final de la semana, tiene 15 visitas y 5 reuniones. Al mes, 60 visitas y 20 reuniones. De esas, hace 5 demos y cierra 3 ventas. Su ingreso: base S/2,958 + comisiones S/490 + bono S/850 + MRR S/252 = S/4,550. El esfuerzo se traduce en dinero. El que no visita, no vende.', NULL, NULL, NULL, 40);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'El Pitch de 30 Segundos – La Puerta de Entrada', 'El pitch de 30 segundos es la herramienta que engancha al cliente desde el primer momento. Debe ser breve, contundente y conectar con el dolor del cliente. No es una lista de características; es una declaración de valor que deja al cliente con una sola pregunta: "¿Cómo lo vemos?". El pitch debe memorizarse y adaptarse al contexto del cliente.', 'Un Hunter entra a un restaurante y dice: "INVU POS es el sistema operativo que usan más de 5,000 restaurantes en Latam. A diferencia de los POS locales, incluimos facturación electrónica nativa, llegamos llave en mano y te dejamos el restaurante operando desde el día uno. No vendemos un POS, vendemos una operación rentable." El dueño, que ha estado batallando con su facturación electrónica, responde: "¿Cómo lo vemos?" El Hunter ya tiene la reunión.', NULL, NULL, NULL, 41);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'Las 7 Preguntas del Hunter – El Mapa del Tesoro', 'El Hunter tiene 7 preguntas que revelan la calificación del cliente, sus dolores y los módulos que necesita. Sin estas preguntas, el Hunter está navegando sin mapa. Las preguntas cubren: facturación y sedes, sistema actual y dolor, facturación electrónica, recetas costeadas, número de cajas, delivery y ecommerce, y tomador de decisión y timeline. El diagnóstico es el mapa; el cierre es el tesoro.', 'En una primera reunión, el Hunter hace las 7 preguntas en 5 minutos. Descubre que el cliente tiene 3 sedes, paga Nubefact aparte, no tiene recetas costeadas, y quiere implementar QR y fidelización. El Hunter sabe exactamente qué cotizar: INVU Central + 3 licencias Sucursal + QR + Loyalty. El diagnóstico es el mapa; el cierre es el tesoro.', NULL, NULL, NULL, 42);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'La Escalera Base – Protección y Motivación para el Hunter', 'El programa Hunters tiene una escalera base que protege al vendedor en sus primeras ventas: 1 venta = S/1,258, 2 ventas = S/2,108, 3 ventas = S/2,958. Esto permite al vendedor estabilizarse y enfocarse en construir mercado, sin la presión del "todo o nada". Además, una venta grande (setup S/15,000+) vale por 3 ventas. La escalera es el colchón que permite al Hunter aprender y crecer sin miedo.', 'Un Hunter nuevo cierra su primera venta en el mes 1. Cobra S/1,258. No es un sueldo enorme, pero es suficiente para que no se desmotive. En el mes 2, cierra 2 ventas: S/2,108. En el mes 3, cierra 3 ventas: S/2,958. Ya estabilizado, en el mes 4 cierra 5 ventas: base S/2,958 + comisiones + bono S/850 = S/4,298. La escalera lo llevó desde la incertidumbre a un ingreso sólido.', NULL, NULL, NULL, 43);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', 'Comisiones desde la Venta 4 – El Ingreso sin Techo', 'Desde la cuarta venta, el Hunter gana 10% sobre setup facturado y pagado, 3% MRR mensual sobre licencias activas durante 12 meses, y 3% sobre hardware. Las comisiones se suman a la base, no la reemplazan. El ingreso del Hunter no tiene techo: cada venta adicional es puro ingreso incremental. Es el combustible que impulsa al Hunter a buscar más y más ventas.', 'Un Hunter cierra 7 ventas en un mes. Base: S/2,958. Comisiones de setup de las ventas 4 a 7: 10% de S/700 = S/980. Bono Top Performer: S/1,020. Cola MRR de las licencias activas: S/504. Ingreso total: S/5,462. Cada venta adicional es puro ingreso extra. No hay techo.', NULL, NULL, NULL, 44);
